import React, { useEffect, useMemo, useState } from "react";
import { Helmet } from "react-helmet-async";
import { useSearchParams } from "react-router-dom";
import {
  FiActivity,
  FiArrowRight,
  FiBarChart2,
  FiCheck,
  FiChevronRight,
  FiClock,
  FiCode,
  FiCopy,
  FiEye,
  FiEyeOff,
  FiKey,
  FiMenu,
  FiPlus,
  FiSearch,
  FiSend,
  FiSettings,
  FiTerminal,
  FiX,
} from "react-icons/fi";
import { Dialog, Panel } from "../StreamWorkspace/WorkspaceUI";
import Dashboard from "./Dashboard";
import FilterPopover from "./FilterPopover";
import ExportMenu from "./ExportMenu";
import Webhooks from "./Webhooks";
import { queryEvents } from "./filterModel";
import { loadProjectResources, saveProjectResources } from "./projectResourceStore";
import { deleteDashboard as deleteDashboardResource, removeDashboardWidget, saveDashboardWidget, updateDashboard as updateDashboardResource, upsertDashboard } from "./dashboardResourceModel";
import plotuneLogo from "../assets/logo.png";
import "../StreamWorkspace/workspace.css";
import "./stream.css";
import {
  initialProjects,
  CAPTURE_ENDPOINT,
  MCP_ENDPOINT,
  SNAPSHOT,
  EVENTS_PER_PAGE,
  cursorPage,
  createSimulatedFirstEvent,
  previewValue,
  ingestionSnippet,
  mcpSnippet,
} from "./eventModel";

const navigation = [
  ["events", "Events", FiActivity],
  ["dashboards", "Dashboards", FiBarChart2],
  ["api", "API setup", FiCode],
  ["mcp", "MCP setup", FiTerminal],
  ["webhooks", "Webhooks", FiSend],
  ["settings", "Project Settings", FiSettings],
];
const eventTime = (value) => new Date(value).toISOString().slice(11, 23);
const eventDate = (value) =>
  new Date(value).toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    timeZone: "UTC",
  });
const mockKey = (id) =>
  `plt_demo_${id}_${Math.random().toString(16).slice(2, 10)}`;

export default function DemoWorkspace() {
  const [params, setParams] = useSearchParams();
  const view = navigation.some(([id]) => id === params.get("view"))
    ? params.get("view")
    : "events";
  const [projects, setProjects] = useState(initialProjects);
  const projectId = projects.some((p) => p.id === params.get("project"))
    ? params.get("project")
    : "first";
  const project = projects.find((p) => p.id === projectId);
  const [search, setSearch] = useState("");
  const [name, setName] = useState("All events");
  const [range, setRange] = useState("24h");
  const [deviceId, setDeviceId] = useState("all");
  const [sessionId, setSessionId] = useState("all");
  const [startAt, setStartAt] = useState("");
  const [endAt, setEndAt] = useState("");
  const [nativeOpen, setNativeOpen] = useState(null);
  const [nativeSearch, setNativeSearch] = useState("");
  const [cursorStack, setCursorStack] = useState([null]);
  const [resources, setResources] = useState(loadProjectResources);
  const [filterId, setFilterId] = useState(null);
  const [conditions, setConditions] = useState([]);
  const [webhooks, setWebhooks] = useState({});
  const [language, setLanguage] = useState("curl");
  const [revealed, setRevealed] = useState(false);
  const [dialog, setDialog] = useState(null);
  const [navOpen, setNavOpen] = useState(false);
  const [toast, setToast] = useState("");
  const [projectName, setProjectName] = useState("");
  const [creatingName, setCreatingName] = useState("");
  const [pending, setPending] = useState({});
  const [accepting, setAccepting] = useState(false);
  const [clock, setClock] = useState(Date.parse(SNAPSHOT));
  const [monthlyAccepted, setMonthlyAccepted] = useState(15320);
  const [members, setMembers] = useState(() => Object.fromEntries(initialProjects.map((p, i) => [p.id, [
    { id: `${p.id}-owner`, name: i === 0 ? "Vera K. (you)" : "You", email: "engineer@example.test", role: "Owner" },
  ]])));
  const [inviteEmail, setInviteEmail] = useState("");
  const [inviteRole, setInviteRole] = useState("Member");
  const [invitePrompt, setInvitePrompt] = useState({});
  const [mcpStates, setMcpStates] = useState({});
  const [accountOpen, setAccountOpen] = useState(false);
  const projectFilters = resources.filters[projectId] || [];
  const projectDashboards = resources.dashboards[projectId] || [];
  const mcpState = mcpStates[projectId] || "Not checked";
  const hasEvents = project.events.length > 0;
  const filtered = useMemo(
    () =>
      queryEvents(project.events, {
        search,
        name,
        range,
        deviceId,
        sessionId,
        startAt,
        endAt,
        now: new Date(clock).toISOString(),
        conditions,
      }),
    [project.events, search, name, range, deviceId, sessionId, startAt, endAt, clock, conditions],
  );
  const page = useMemo(
    () => cursorPage(filtered, cursorStack[cursorStack.length - 1], EVENTS_PER_PAGE),
    [filtered, cursorStack],
  );
  const eventNames = [...new Set(project.events.map((e) => e.event))].sort();
  const deviceIds = [...new Set(project.events.map((e) => e.device_id).filter(Boolean))].sort();
  const sessionIds = [...new Set(project.events.map((e) => e.session_id).filter(Boolean))].sort();
  const pendingEvents = pending[projectId] || [];
  const latest = [...project.events].sort(
    (a, b) => Date.parse(b.timestamp) - Date.parse(a.timestamp),
  )[0];
  const notify = (text) => setToast(text);
  const setLocation = (nextView, nextProject = projectId, preserveContext = false) => {
    setParams({
      ...(nextView !== "events" ? { view: nextView } : {}),
      ...(nextProject !== "first" ? { project: nextProject } : {}),
    });
    setNavOpen(false);
    setAccountOpen(false);
    setDialog(null);
    if (!preserveContext) {
      setSearch("");
      setName("All events");
      setRange("24h");
      setDeviceId("all"); setSessionId("all"); setStartAt(""); setEndAt(""); setNativeOpen(null);
      setFilterId(null);
      setConditions([]);
    }
    setCursorStack([null]);
    setRevealed(false);
    window.scrollTo({ top: 0 });
  };
  const updateProject = (change) =>
    setProjects((prev) =>
      prev.map((p) => (p.id === projectId ? { ...p, ...change } : p)),
    );
  const copy = async (text, what) => {
    try {
      await navigator.clipboard.writeText(text);
      notify(`${what} copied.`);
    } catch {
      notify("Clipboard unavailable. Select the text and copy it manually.");
    }
  };
  const sendPreview = () => {
    if (accepting) return;
    setAccepting(true);
  };
  useEffect(() => {
    setRevealed(false);
    setSearch("");
    setName("All events");
    setCursorStack([null]);
    setAccepting(false);
    setFilterId(null);
    setConditions([]);
    setProjectName(project.name);
  }, [projectId, project.name]);
  useEffect(() => { saveProjectResources(resources); }, [resources]);
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(""), 4500);
    return () => clearTimeout(t);
  }, [toast]);
  useEffect(() => {
    if (!accepting) return;
    const t = setTimeout(() => {
      const stamp = clock + 1000;
      const event = createSimulatedFirstEvent(
        `local-${stamp}-${projectId}`,
        new Date(stamp).toISOString(),
      );
      setProjects((prev) =>
        prev.map((p) =>
          p.id === projectId ? { ...p, events: [event, ...p.events] } : p,
        ),
      );
      setClock(stamp);
      setMonthlyAccepted((n) => n + 1);
      setAccepting(false);
      setSearch("");
      setName("All events");
      setRange("24h");
      setDeviceId("all"); setSessionId("all"); setStartAt(""); setEndAt("");
      setNativeOpen(null);
      setCursorStack([null]);
      setParams(projectId === "first" ? {} : { project: projectId });
      if (project.events.length === 0) setInvitePrompt((prev) => ({ ...prev, [projectId]: true }));
      notify(`First event received · ${event.event}`);
    }, 700);
    return () => clearTimeout(t);
  }, [accepting, clock, projectId, setParams]);
  useEffect(() => {
    if (mcpState !== "Checking") return;
    const t = setTimeout(
      () =>
        setMcpStates((prev) => ({
          ...prev,
          [projectId]: "Demo connection ready",
        })),
      900,
    );
    return () => clearTimeout(t);
  }, [mcpState, projectId]);
  const resetFilters = () => {
    setSearch("");
    setName("All events");
    setRange("24h");
    setDeviceId("all"); setSessionId("all"); setStartAt(""); setEndAt(""); setNativeOpen(null);
    setFilterId(null);
    setConditions([]);
    setCursorStack([null]);
  };
  const applyContext = (next = {}) => {
    if (Object.hasOwn(next, "name")) setName(next.name);
    if (Object.hasOwn(next, "deviceId")) setDeviceId(next.deviceId);
    if (Object.hasOwn(next, "sessionId")) setSessionId(next.sessionId);
    if (Object.hasOwn(next, "startAt")) setStartAt(next.startAt);
    if (Object.hasOwn(next, "endAt")) setEndAt(next.endAt);
    if (Object.hasOwn(next, "range")) setRange(next.range);
    setCursorStack([null]);
  };
  const navigateContext = (next) => {
    applyContext(next);
    if (view !== "events") setLocation("events", projectId, true);
  };
  const applyPropertyFilter = (nextConditions, nextFilterId) => {
    setConditions(nextConditions);
    setFilterId(nextFilterId || null);
    setCursorStack([null]);
  };
  const saveFilter = (filterName, nextConditions, existingId = null) => {
    let selectedId = existingId;
    if (!selectedId) selectedId = `${projectId}-filter-${Date.now()}`;
    setResources((current) => {
      const currentFilters = current.filters[projectId] || [];
      const nextFilters = existingId
        ? currentFilters.map((item) => item.id === existingId ? { ...item, conditions: nextConditions.map((condition) => ({ ...condition })) } : item)
        : [...currentFilters, { id: selectedId, name: filterName, conditions: nextConditions.map((condition) => ({ ...condition })) }];
      return { ...current, filters: { ...current.filters, [projectId]: nextFilters } };
    });
    if (!existingId) setFilterId(selectedId);
  };
  const renameFilter = (id, nextName) => setResources((current) => ({
    ...current,
    filters: { ...current.filters, [projectId]: (current.filters[projectId] || []).map((item) => item.id === id ? { ...item, name: nextName } : item) },
  }));
  const deleteFilter = (id) => {
    setResources((current) => ({ ...current, filters: { ...current.filters, [projectId]: (current.filters[projectId] || []).filter((item) => item.id !== id) } }));
    if (filterId === id) { setFilterId(null); setConditions([]); }
  };
  const openDashboard = (dashboardId) => setParams({ view: "dashboards", ...(projectId !== "first" ? { project: projectId } : {}), dashboard: dashboardId });
  const createDashboard = (dashboard) => setResources((current) => ({ ...current, dashboards: { ...current.dashboards, [projectId]: upsertDashboard(current.dashboards[projectId] || [], dashboard) } }));
  const updateDashboard = (id, update) => setResources((current) => ({
    ...current,
    dashboards: { ...current.dashboards, [projectId]: updateDashboardResource(current.dashboards[projectId] || [], id, update) },
  }));
  const deleteDashboard = (id) => {
    setResources((current) => ({ ...current, dashboards: { ...current.dashboards, [projectId]: deleteDashboardResource(current.dashboards[projectId] || [], id) } }));
    if (params.get("dashboard") === id) setLocation("dashboards");
  };
  const queuePreviewEvent = () => {
    const count = pendingEvents.length;
    const stamp = clock + (count + 1) * 1000;
    const candidates = [
      {
        event: "sensor.reading",
        properties: { range_m: 2.6 + count * 0.1, confidence: 0.91 + count * 0.01, state: "valid" },
      },
      {
        event: "test.failed",
        properties: { suite: "sensor_check", result: "failed", attempt: count + 1 },
      },
      {
        event: "environment",
        properties: { temperature: 21.8 + count * 0.1, humidity: 40.2, state: "stable" },
      },
    ];
    const e = {
      ...candidates[count % candidates.length],
      id: `pending-${projectId}-${stamp}`,
      timestamp: new Date(stamp).toISOString(),
    };
    setPending((prev) => ({
      ...prev,
      [projectId]: [...(prev[projectId] || []), e],
    }));
  };
  const acceptPending = () => {
    setProjects((prev) =>
      prev.map((p) =>
        p.id === projectId
          ? { ...p, events: [...pendingEvents, ...p.events] }
          : p,
      ),
    );
    setClock((c) =>
      Math.max(c, ...pendingEvents.map((e) => Date.parse(e.timestamp))),
    );
    setMonthlyAccepted((n) => n + pendingEvents.length);
    setPending((prev) => ({ ...prev, [projectId]: [] }));
    resetFilters();
    notify("New demo events added. Filters reset so you can inspect them.");
  };
  const apiKey = (
    <div className="st-key">
      <FiKey />
      <code aria-label="Project API key">
        {revealed ? project.key : "plt_demo_••••••••••••••••"}
      </code>
      <button
        className="sw-icon-button"
        aria-label={revealed ? "Hide API key" : "Reveal API key"}
        onClick={() => setRevealed((v) => !v)}
      >
        {revealed ? <FiEyeOff /> : <FiEye />}
      </button>
      <button
        className="sw-icon-button"
        aria-label="Copy API key"
        onClick={() => copy(project.key, "Demo API key")}
      >
        <FiCopy />
      </button>
    </div>
  );
  const example = (compact = false) => (
    <div className={`st-integration ${compact ? "compact" : ""}`}>
      <div className="st-example-heading">
        <strong>Send an event over HTTP</strong>
        <span>Any language. Any JSON properties.</span>
      </div>
      <div className="sw-tabs" role="group" aria-label="Integration language">
        {["curl", "Python", "C/C++", "Arduino / ESP32", "MATLAB", "ROS 2", "CAPL"].map((l) => (
          <button
            key={l}
            className={language === l ? "active" : ""}
            aria-pressed={language === l}
            onClick={() => setLanguage(l)}
          >
            {l}
          </button>
        ))}
      </div>
      <div className="st-snippet">
        <button
          className="sw-button st-copy-code"
          aria-label="Copy integration snippet"
          onClick={() =>
            copy(
              ingestionSnippet(language, project.key),
              "Integration example",
            )
          }
        >
          <FiCopy />
          Copy
        </button>
        <pre
          className="sw-code"
          tabIndex={0}
          aria-label={`${language} integration snippet`}
        >
          {ingestionSnippet(language, project.key)}
        </pre>
      </div>
      <p className="st-contract-note">
        Uses this project's demo key. Replace it with your project key; this demo doesn't send requests.
        {language === "C/C++" ? " Requires libcurl." : ""}
        {language === "Arduino / ESP32" ? " Paste the server's root CA certificate into ROOT_CA." : ""}
        {language === "ROS 2" ? " Runs as a standalone rclpy node; batch events for high-rate topics." : ""}
        {language === "CAPL" ? " Calls curl.exe through sysExecCmd; adjust message and signal names to your DBC." : ""}
      </p>
    </div>
  );
  const firstEvent = (
    <div className="st-first-event">
      <span className="st-first-icon">
        <FiTerminal />
      </span>
      <p className="sw-eyebrow">PROJECT CREATED</p>
      <h2>Waiting for your first event</h2>
      <p>
        Stream is listening. Send an HTTP event from any system to see it arrive here.
      </p>
      <div className={`st-listening ${accepting ? "receiving" : ""}`} role="status">
        <span className="st-listening-dot" />
        {accepting ? "Receiving motor.sample…" : "Listening for events"}
      </div>
      {example(true)}
      <div className="st-activation-preview">
        <button
          className="sw-button sw-primary"
          disabled={accepting}
          onClick={sendPreview}
        >
          {accepting ? "Receiving event…" : "Simulate event received"}
          <FiArrowRight />
        </button>
      </div>
      <p className="st-first-foot">Use the example above to send your first event. The simulation demonstrates the experience in this browser.</p>
    </div>
  );

  function explorer() {
    if (!hasEvents) return firstEvent;
    return (
      <>
        {nativeOpen && <button className="st-native-dismiss" aria-label="Close native filter" tabIndex={-1} onClick={() => setNativeOpen(null)} />}
        {invitePrompt[projectId] && (
          <div className="st-invite-prompt">
            <div><strong>First event received</strong><span>motor.sample · just now</span></div>
            <button className="sw-button sw-primary" onClick={() => { setInvitePrompt((prev) => ({ ...prev, [projectId]: false })); setLocation("settings"); }}>Invite your colleagues</button>
            <button className="sw-link" onClick={() => setInvitePrompt((prev) => ({ ...prev, [projectId]: false }))}>Skip</button>
          </div>
        )}
        <div className="st-event-summary">
          <span>
            <strong>{project.events.length}</strong> demo events in this project
          </span>
          <span>
            Last received{" "}
            <strong>{latest ? eventTime(latest.timestamp) : "—"}</strong> UTC
          </span>
        </div>
        <div className="sw-toolbar st-filters">
          <label className="sw-search">
            <FiSearch />
            <input
              aria-label="Search events and properties"
              placeholder="Search event names and properties…"
              value={search}
              onChange={(e) => {
                setSearch(e.target.value);
                setCursorStack([null]);
              }}
            />
          </label>
          <select aria-label="Filter event name" value={name} onChange={(e) => applyContext({ name: e.target.value })}>
            <option>All events</option>
            {eventNames.map((n) => (
              <option key={n}>{n}</option>
            ))}
          </select>
          <select aria-label="Event time range" value={range} onChange={(e) => applyContext({ range: e.target.value, startAt: "", endAt: "" })}>
            <option value="1h">Last hour</option>
            <option value="24h">Last 24 hours</option>
            <option value="7d">Last 7 days</option>
            <option value="all">All time</option>
          </select>
          <div className="st-native-filter">
            <button type="button" className={`sw-button ${deviceId !== "all" ? "is-active" : ""}`} aria-expanded={nativeOpen === "device"} onClick={() => setNativeOpen(nativeOpen === "device" ? null : "device")}>Device{deviceId === "all" ? "" : ` · ${deviceId === "unspecified" ? "Unspecified" : deviceId}`}</button>
            {nativeOpen === "device" && <div className="st-native-popover" role="dialog" aria-label="Filter by device"><strong>Device ID</strong><input aria-label="Search device IDs" type="search" placeholder="Search identifiers" value={nativeSearch} onChange={(e) => setNativeSearch(e.target.value)} /><button type="button" onClick={() => { applyContext({ deviceId: "all" }); setNativeOpen(null); }}>All devices</button><button type="button" onClick={() => { applyContext({ deviceId: "unspecified" }); setNativeOpen(null); }}>Unspecified</button>{deviceIds.filter((id) => id.toLowerCase().includes(nativeSearch.toLowerCase())).map((id) => <button type="button" key={id} onClick={() => { applyContext({ deviceId: id }); setNativeOpen(null); }}>{id}</button>)}{!deviceIds.length && <small>No device IDs in project</small>}</div>}
          </div>
          <div className="st-native-filter">
            <button type="button" className={`sw-button ${sessionId !== "all" ? "is-active" : ""}`} aria-expanded={nativeOpen === "session"} onClick={() => setNativeOpen(nativeOpen === "session" ? null : "session")}>Session{sessionId === "all" ? "" : ` · ${sessionId === "unspecified" ? "Unspecified" : sessionId}`}</button>
            {nativeOpen === "session" && <div className="st-native-popover" role="dialog" aria-label="Filter by session"><strong>Session ID</strong><input aria-label="Search session IDs" type="search" placeholder="Search identifiers" value={nativeSearch} onChange={(e) => setNativeSearch(e.target.value)} /><button type="button" onClick={() => { applyContext({ sessionId: "all", name: "All events" }); setNativeOpen(null); }}>All sessions</button><button type="button" onClick={() => { applyContext({ sessionId: "unspecified", name: "All events" }); setNativeOpen(null); }}>Unspecified</button>{sessionIds.filter((id) => id.toLowerCase().includes(nativeSearch.toLowerCase())).map((id) => <button type="button" key={id} onClick={() => { applyContext({ sessionId: id, name: "All events" }); setNativeOpen(null); }}>{id}</button>)}{!sessionIds.length && <small>No session IDs in project</small>}</div>}
          </div>
          <div className="st-native-filter">
            <button type="button" className={`sw-button ${startAt || endAt ? "is-active" : ""}`} aria-expanded={nativeOpen === "time"} onClick={() => setNativeOpen(nativeOpen === "time" ? null : "time")}><FiClock /> {startAt || endAt ? `${startAt ? new Date(startAt).toISOString().slice(11, 16) : "…"}–${endAt ? new Date(endAt).toISOString().slice(11, 16) : "…"} UTC` : "Time range"}</button>
            {nativeOpen === "time" && <div className="st-native-popover st-time-popover" role="dialog" aria-label="Custom event time range"><strong>Event time · UTC</strong><label>From<input type="datetime-local" value={startAt ? new Date(Date.parse(startAt)).toISOString().slice(0,16) : ""} onChange={(e) => applyContext({ startAt: e.target.value ? new Date(`${e.target.value}Z`).toISOString() : "", range: "all" })} /></label><label>Until (exclusive)<input type="datetime-local" value={endAt ? new Date(Date.parse(endAt)).toISOString().slice(0,16) : ""} onChange={(e) => applyContext({ endAt: e.target.value ? new Date(`${e.target.value}Z`).toISOString() : "", range: "all" })} /></label>{startAt && endAt && Date.parse(startAt) > Date.parse(endAt) && <small role="alert">Start must be before end.</small>}<button type="button" onClick={() => { applyContext({ startAt: "", endAt: "", range: "24h" }); setNativeOpen(null); }}>Reset time</button></div>}
          </div>
          <FilterPopover
            events={project.events}
            filters={projectFilters}
            activeFilterId={filterId}
            conditions={conditions}
            onApply={applyPropertyFilter}
            onSave={saveFilter}
            onRename={renameFilter}
            onDelete={deleteFilter}
            referenceCount={(id) => (projectDashboards || []).flatMap((dashboard) => dashboard.widgets || []).filter((widget) => widget.filterId === id).length}
          />
          <ExportMenu
            events={project.events}
            query={{ search, name, range, deviceId, sessionId, startAt, endAt, now: new Date(clock).toISOString(), conditions }}
            projectName={project.name}
          />
          {(search || name !== "All events" || range !== "24h" || deviceId !== "all" || sessionId !== "all" || startAt || endAt || conditions.length > 0) && (
            <button className="sw-link" onClick={resetFilters}>
              Clear filters
            </button>
          )}
        </div>
        <div className="st-list-status">
          <span>{page.items.length} events on this page · {EVENTS_PER_PAGE} per page · newest first · UTC</span>
          <button className="sw-link" onClick={queuePreviewEvent}>
            <FiPlus />
            Simulate incoming event
          </button>
        </div>
        {pendingEvents.length > 0 && (
          <button className="st-new-events" onClick={acceptPending}>
            <FiActivity />
            {pendingEvents.length} new demo{" "}
            {pendingEvents.length === 1 ? "event" : "events"} · Show newest
            <FiArrowRight />
          </button>
        )}
        <div className="sw-panel st-events-panel">
          {filtered.length ? (
            <div className="sw-table-wrap">
              <table className="sw-table st-table">
                <thead>
                  <tr>
                    <th>Timestamp · UTC</th>
                    <th>Event</th>
                    <th>Properties</th>
                    <th aria-label="Open event" />
                  </tr>
                </thead>
                <tbody>
                  {page.items.map((e) => (
                    <tr key={e.id}>
                      <td>
                        <button
                          className="st-time-button"
                          onClick={() => setDialog({ kind: "event", event: e })}
                          title={e.timestamp}
                        >
                          <time dateTime={e.timestamp}>
                            {eventTime(e.timestamp)}
                          </time>
                          <small>{eventDate(e.timestamp)}</small>
                        </button>
                      </td>
                      <td>
                        <button
                          className="sw-link sw-mono"
                          onClick={() => setDialog({ kind: "event", event: e })}
                        >
                          {e.event}
                        </button>
                      </td>
                      <td>
                        <div className="st-property-preview">
                          {(e.device_id || e.session_id) ? <div className="st-event-context"><span>Device <b>{e.device_id || "Unspecified"}</b></span><span>Session <b>{e.session_id || "Unspecified"}</b></span></div> : <span className="st-event-context-unspecified">Context unspecified</span>}
                          {Object.entries(e.properties)
                            .slice(0, 3)
                            .map(([k, v]) => (
                              <span
                                key={k}
                                title={`${k}: ${JSON.stringify(v)}`}
                              >
                                <em>{k}</em>
                                <b>{previewValue(v)}</b>
                              </span>
                            ))}
                          {Object.keys(e.properties).length > 3 && (
                            <button
                              className="st-more-properties"
                              aria-label={`Show all properties for ${e.event} at ${eventTime(e.timestamp)}`}
                              onClick={() =>
                                setDialog({ kind: "event", event: e })
                              }
                            >
                              +{Object.keys(e.properties).length - 3}
                            </button>
                          )}
                          {Object.keys(e.properties).length === 0 && (
                            <span className="st-no-properties">
                              No properties
                            </span>
                          )}
                        </div>
                      </td>
                      <td>
                        <button
                          className="sw-icon-button"
                          aria-label={`Inspect ${e.event} at ${eventTime(e.timestamp)}`}
                          onClick={() => setDialog({ kind: "event", event: e })}
                        >
                          <FiChevronRight />
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : (
            <div className="st-filter-empty">
              <FiSearch />
              <h2>No events match these filters</h2>
              <p>
                Search another event name or property, or widen the time range.
              </p>
              <button className="sw-button" onClick={resetFilters}>
                Clear filters
              </button>
            </div>
          )}
        </div>
        {(page.nextCursor || cursorStack.length > 1) && (
          <nav className="st-pagination" aria-label="Event pages">
            <button
              className="sw-button"
              disabled={cursorStack.length === 1}
              onClick={() => setCursorStack((current) => current.slice(0, -1))}
            >
              Previous
            </button>
            <span>{EVENTS_PER_PAGE} events per page</span>
            <button
              className="sw-button"
              disabled={!page.nextCursor}
              onClick={() => page.nextCursor && setCursorStack((current) => [...current, page.nextCursor])}
            >
              Next
            </button>
          </nav>
        )}
        <p className="st-explorer-foot">
          Event names and properties are defined by your systems. No schema
          configuration is required.
        </p>
      </>
    );
  }
  function apiSetup() {
    return (
      <>
        <Panel
          title="Project connection"
          meta={project.name}
          action={<button className="sw-link" onClick={() => setDialog({ kind: "regenerate" })}>Regenerate key</button>}
        >
          <div className="st-connection st-api-credentials">
            <label>
              Project ID
              <div className="st-endpoint">
                <code>{project.id}</code>
                <button
                  className="sw-icon-button"
                  aria-label="Copy project ID"
                  onClick={() => copy(project.id, "Project ID")}
                >
                  <FiCopy />
                </button>
              </div>
            </label>
            <label>Tracker key{apiKey}</label>
            <label>
              Ingestion endpoint
              <div className="st-endpoint">
                <code>{CAPTURE_ENDPOINT}</code>
                <button
                  className="sw-icon-button"
                  aria-label="Copy ingestion endpoint"
                  onClick={() => copy(CAPTURE_ENDPOINT, "Ingestion endpoint")}
                >
                  <FiCopy />
                </button>
              </div>
            </label>
            <p>
              The key selects the project. Choose any event name and send
              arbitrary JSON properties.
            </p>
          </div>
        </Panel>
        <Panel title="Capture an event">
          {example()}
          <div className="st-api-bottom">
            <p>
              Use HTTP from CAPL, C/C++, Python, ROS, MATLAB, Nexus, or any
              other system. No source registration is needed.
            </p>
          </div>
        </Panel>
      </>
    );
  }
  function mcpSetup() {
    return (
      <>
        <Panel title="Query events from your AI agent">
          <div className="st-mcp-intro">
            <span className="st-first-icon">
              <FiTerminal />
            </span>
            <div>
              <h3>Your event history, available through MCP.</h3>
              <p>
                Connect an MCP-capable client to query this project's event
                names, timestamps, and properties.
              </p>
              <p className="st-muted">
                This connection provides event-history access. It does not
                control hardware.
              </p>
            </div>
          </div>
          <div className="st-mcp-example">
            <span>Try asking</span>
            <q>
              Find recent test.failed events and summarize their properties.
            </q>
          </div>
        </Panel>
        <Panel title="MCP connection" meta={project.name}>
          <div className="st-connection">
            <label>
              MCP endpoint
              <div className="st-endpoint">
                <code>{MCP_ENDPOINT}</code>
                <button
                  className="sw-icon-button"
                  aria-label="Copy MCP endpoint"
                  onClick={() => copy(MCP_ENDPOINT, "MCP endpoint")}
                >
                  <FiCopy />
                </button>
              </div>
            </label>
            <p>
              Add the illustrative configuration to your client. The mock
              project key below selects <strong>{project.name}</strong>.
            </p>
          </div>
          <div className="st-mcp-config">
            <div className="sw-code-head">
              <span>Illustrative client configuration</span>
              <button
                className="sw-link"
                onClick={() =>
                  copy(
                    mcpSnippet(project.key),
                    "Illustrative MCP configuration",
                  )
                }
              >
                <FiCopy />
                Copy configuration
              </button>
            </div>
            <pre
              className="sw-code"
              tabIndex={0}
              aria-label="MCP configuration"
            >
              {mcpSnippet(project.key)}
            </pre>
            <p className="st-contract-note">
              Configuration format varies by client. Endpoint, key, and
              connection check are mocked.
            </p>
          </div>
          <div className="st-mcp-status">
            <span
              className={`st-connection-dot ${mcpState === "Demo connection ready" ? "ready" : ""}`}
            />
            <span role="status">
              {mcpState === "Checking" ? "Checking demo connection…" : mcpState}
            </span>
            <button
              className="sw-button"
              disabled={mcpState === "Checking"}
              onClick={() =>
                setMcpStates((prev) => ({ ...prev, [projectId]: "Checking" }))
              }
            >
              {mcpState === "Demo connection ready"
                ? "Check again"
                : "Check demo connection"}
            </button>
          </div>
        </Panel>
      </>
    );
  }
  function settings() {
    return (
      <>
        <Panel title="Project">
          <form
            className="st-settings-form"
            onSubmit={(e) => {
              e.preventDefault();
              updateProject({ name: projectName.trim() });
              notify("Project name updated for this session.");
            }}
          >
            <label>
              Project name
              <input
                required
                maxLength={64}
                value={projectName}
                onChange={(e) => setProjectName(e.target.value)}
              />
            </label>
            <p>
              This project keeps its event history together. Event properties
              remain unrestricted.
            </p>
            <button
              className="sw-button sw-primary"
              disabled={
                !projectName.trim() || projectName.trim() === project.name
              }
              type="submit"
            >
              Save name
            </button>
          </form>
        </Panel>
        <Panel title="Project members" meta={`${(members[projectId] || []).length} people`}>
          <form className="st-invite-form" onSubmit={(e) => {
            e.preventDefault();
            const email = inviteEmail.trim().toLowerCase();
            if (!email) return;
            setMembers((prev) => ({ ...prev, [projectId]: [...(prev[projectId] || []), { id: `${projectId}-${Date.now()}`, name: email.split("@")[0], email, role: inviteRole }] }));
            setInviteEmail("");
            notify("Colleague added to this preview.");
          }}>
            <label>Email<input type="email" required placeholder="colleague@company.com" value={inviteEmail} onChange={(e) => setInviteEmail(e.target.value)} /></label>
            <label>Role<select value={inviteRole} onChange={(e) => setInviteRole(e.target.value)}><option>Admin</option><option>Member</option></select></label>
            <button className="sw-button sw-primary" type="submit">Invite colleague</button>
          </form>
          <div className="st-member-list">{(members[projectId] || []).map((member) => <div key={member.id}>
            <div><strong>{member.name}</strong><span>{member.email}</span></div>
            {member.role === "Owner" ? <span className="st-role owner">Owner</span> : <>
              <select aria-label={`Role for ${member.email}`} value={member.role} onChange={(e) => setMembers((prev) => ({ ...prev, [projectId]: prev[projectId].map((m) => m.id === member.id ? { ...m, role: e.target.value } : m) }))}><option>Admin</option><option>Member</option></select>
              <button className="sw-link" onClick={() => setMembers((prev) => ({ ...prev, [projectId]: prev[projectId].filter((m) => m.id !== member.id) }))}>Remove</button>
            </>}
          </div>)}</div>
          <p className="st-members-note">Owners control project and membership settings. Admins manage the project and members. Members can inspect and query events.</p>
        </Panel>
      </>
    );
  }
  function details() {
    if (!dialog) return null;
    const close = () => setDialog(null);
    if (dialog.kind === "event") {
      const e = dialog.event;
      return (
        <Dialog title={e.event} subtitle="Event detail" onClose={close}>
          <div className="sw-detail-body st-event-detail">
            <div className="st-detail-field">
              <span>Exact timestamp · UTC</span>
              <div>
                <code>{e.timestamp}</code>
                <button
                  className="sw-icon-button"
                  aria-label="Copy event timestamp"
                  onClick={() => copy(e.timestamp, "Timestamp")}
                >
                  <FiCopy />
                </button>
              </div>
            </div>
            <div className="st-detail-field">
              <span>Event name</span>
              <div>
                <code>{e.event}</code>
                <button
                  className="sw-icon-button"
                  aria-label="Copy event name"
                  onClick={() => copy(e.event, "Event name")}
                >
                  <FiCopy />
                </button>
              </div>
            </div>
            <div className="st-detail-field st-context-detail">
              <span>Device ID</span><div><code>{e.device_id || "Unspecified"}</code>{e.device_id && <button className="sw-button" type="button" onClick={() => { navigateContext({ deviceId: e.device_id, name: "All events" }); setDialog(null); notify(`Showing events from ${e.device_id}.`); }}>View device events</button>}</div>
            </div>
            <div className="st-detail-field st-context-detail">
              <span>Session ID</span><div><code>{e.session_id || "Unspecified"}</code>{e.session_id && <button className="sw-button" type="button" onClick={() => { navigateContext({ sessionId: e.session_id, name: "All events" }); setDialog(null); notify(`Showing all event types in ${e.session_id}.`); }}>View session events</button>}</div>
            </div>
            <div className="sw-code-head">
              <h3>Properties</h3>
              <button
                className="sw-link"
                onClick={() =>
                  copy(JSON.stringify(e.properties, null, 2), "Properties JSON")
                }
              >
                <FiCopy />
                Copy JSON
              </button>
            </div>
            <pre
              className="sw-code st-properties-json"
              tabIndex={0}
              aria-label="Complete event properties"
            >
              {JSON.stringify(e.properties, null, 2)}
            </pre>
            <button
              className="sw-button"
              onClick={() =>
                copy(
                  JSON.stringify(
                    {
                      event: e.event,
                      ...(e.device_id ? { device_id: e.device_id } : {}),
                      ...(e.session_id ? { session_id: e.session_id } : {}),
                      timestamp: e.timestamp,
                      properties: e.properties,
                    },
                    null,
                    2,
                  ),
                  "Event payload",
                )
              }
            >
              <FiCopy />
              Copy complete event
            </button>
            <p className="st-contract-note">
              Device and session IDs are optional sender supplied context. They are
              not registered or generated by Stream. Properties remain arbitrary.
            </p>
          </div>
        </Dialog>
      );
    }
    if (dialog.kind === "create")
      return (
        <Dialog
          title="Create a project"
          subtitle="Give your event history a place to live."
          onClose={close}
        >
          <form
            className="sw-detail-body st-create-form"
            onSubmit={(e) => {
              e.preventDefault();
              const id = `project-${Date.now()}`;
              setProjects((prev) => [
                ...prev,
                { id, name: creatingName.trim(), key: mockKey(id), events: [] },
              ]);
              setMembers((prev) => ({ ...prev, [id]: [{ id: `${id}-owner`, name: "You", email: "engineer@example.test", role: "Owner" }] }));
              setLocation("events", id);
              notify(
                "Demo project created. Send your first event to explore the flow.",
              );
            }}
          >
            <label>
              Project name
              <input
                autoFocus
                required
                maxLength={64}
                placeholder="e.g. Sensor validation"
                value={creatingName}
                onChange={(e) => setCreatingName(e.target.value)}
              />
            </label>
            <p>
              A demo API key is generated automatically. You can send any event
              name and arbitrary properties.
            </p>
            <button
              className="sw-button sw-primary"
              type="submit"
              disabled={!creatingName.trim()}
            >
              Create project <FiArrowRight />
            </button>
          </form>
        </Dialog>
      );
    return (
      <Dialog
        title="Regenerate the demo key?"
        subtitle={project.name}
        onClose={close}
      >
        <div className="sw-detail-body">
          <p>
            In a real project, the old key would stop accepting requests. This
            preview only replaces the mock key in your setup examples.
          </p>
          <div className="sw-dialog-actions">
            <button className="sw-button" onClick={close}>
              Cancel
            </button>
            <button
              className="sw-button sw-primary"
              onClick={() => {
                updateProject({ key: mockKey(projectId) });
                setRevealed(false);
                setMcpStates((prev) => ({
                  ...prev,
                  [projectId]: "Not checked",
                }));
                close();
                notify("Demo key regenerated. Setup examples are updated.");
              }}
            >
              Regenerate demo key
            </button>
          </div>
        </div>
      </Dialog>
    );
  }
  const dashboardId = params.get("dashboard");
  const selectedDashboard = projectDashboards.find((item) => item.id === dashboardId);
  const title = view === "dashboards" ? selectedDashboard?.name || "Dashboards" : navigation.find(([id]) => id === view)[1];
  return (
    <div className="sw-app st-app">
      <Helmet>
        <title>{project.name} · Plotune Stream</title>
        <meta name="robots" content="noindex,nofollow" />
      </Helmet>
      <header className="sw-topbar">
        <button
          className="sw-icon-button sw-menu"
          aria-label="Open workspace navigation"
          aria-expanded={navOpen}
          onClick={() => setNavOpen((v) => !v)}
        >
          <FiMenu />
        </button>
        <a className="sw-brand" href="/" aria-label="Plotune home">
          <img className="st-brand-logo" src={plotuneLogo} alt="" />
          <strong>
            Plotune <span>Stream</span>
          </strong>
        </a>
        <span className="sw-top-divider" />
        <span className="st-top-project">{project.name}</span>
        <div className="sw-top-end">
          <button
            className="sw-avatar st-account"
            aria-label="Demo account"
            aria-expanded={accountOpen}
            onClick={() => setAccountOpen((v) => !v)}
          >
            VK
          </button>
        </div>
        {accountOpen && (
          <div className="st-account-menu">
            <strong>Demo engineer</strong>
            <span>engineer@example.test</span>
            <p>Usage · {monthlyAccepted.toLocaleString("en-US")} / 100,000 events this month</p>
            <small>Preview data · changes reset on reload</small>
            <button className="sw-link" onClick={() => setAccountOpen(false)}>
              Close
            </button>
          </div>
        )}
      </header>
      {navOpen && (
        <button
          className="sw-nav-backdrop"
          aria-label="Close workspace navigation"
          onClick={() => setNavOpen(false)}
        />
      )}
      <aside className={`sw-sidebar ${navOpen ? "is-open" : ""}`}>
        <div className="sw-project-select">
          <span>PROJECT</span>
          <select
            aria-label="Project"
            value={projectId}
            onChange={(e) => setLocation(view, e.target.value)}
          >
            {projects.map((p) => (
              <option key={p.id} value={p.id}>
                {p.name}
              </option>
            ))}
          </select>
          <button
            className="sw-link st-create-link"
            onClick={() => {
              setCreatingName("");
              setDialog({ kind: "create" });
              setNavOpen(false);
            }}
          >
            <FiPlus />
            Create project
          </button>
        </div>
        <nav aria-label="Workspace navigation">
          <div className="sw-nav-group">
            {navigation.slice(0, 2).map(([id, label, Icon]) => (
              <button
                key={id}
                className={view === id ? "active" : ""}
                aria-current={view === id ? "page" : undefined}
                onClick={() => setLocation(id)}
              >
                <Icon />
                {label}
              </button>
            ))}
          </div>
          <div className="sw-nav-group">
            <p>SETUP</p>
            {navigation.slice(2, 5).map(([id, name, Icon]) => (
              <button
                key={id}
                className={view === id ? "active" : ""}
                aria-current={view === id ? "page" : undefined}
                onClick={() => setLocation(id)}
              >
                <Icon />
                {name}
              </button>
            ))}
          </div>
          <button
            className={`sw-settings-link ${view === "settings" ? "active" : ""}`}
            aria-current={view === "settings" ? "page" : undefined}
            onClick={() => setLocation("settings")}
          >
            <FiSettings />
            Project Settings
          </button>
        </nav>
      </aside>
      <main className="sw-main">
        <div className="sw-breadcrumb">
          Projects
          <FiChevronRight />
          <span>{project.name}</span>
          <FiChevronRight />
          {title}
        </div>
        <div className="sw-page-head">
          <div>
            <h1>{title}</h1>
            <p>
              {view === "events"
                ? "Inspect what your systems send. Event names, timestamps, and properties."
                : view === "dashboards"
                  ? selectedDashboard?.description || (selectedDashboard ? "Project dashboard" : "Project dashboards for recurring event views.")
                : view === "api"
                  ? "Send the first event from any system that can make an HTTP request."
                  : view === "mcp"
                    ? "Query this project’s events from your AI agent."
                    : view === "webhooks"
                      ? "Forward selected events to any HTTPS endpoint."
                      : "Manage the project and the people who can access it."}
            </p>
          </div>
          <div className="sw-page-actions" />
        </div>
        <div className="sw-content">
          {view === "events"
            ? explorer()
            : view === "dashboards"
              ? <Dashboard
                  projectId={projectId}
                  projectName={project.name}
                  events={project.events}
                  now={new Date(clock).toISOString()}
                  dashboards={projectDashboards}
                  filters={projectFilters}
                  selectedDashboardId={dashboardId}
                  onOpen={openDashboard}
                  onBack={() => setLocation("dashboards")}
                  onCreate={createDashboard}
                  onRename={(id, name, description) => updateDashboard(id, { name, description })}
                  onDelete={deleteDashboard}
                  onSaveWidget={(id, widget) => setResources((current) => ({ ...current, dashboards: { ...current.dashboards, [projectId]: saveDashboardWidget(current.dashboards[projectId] || [], id, widget) } }))}
                  onRemoveWidget={(id, widgetId) => setResources((current) => ({ ...current, dashboards: { ...current.dashboards, [projectId]: removeDashboardWidget(current.dashboards[projectId] || [], id, widgetId) } }))}
                />
            : view === "api"
              ? apiSetup()
              : view === "mcp"
                ? mcpSetup()
                : view === "webhooks"
                  ? <Webhooks
                      projectId={projectId}
                      events={project.events}
                      webhooks={webhooks[projectId] || []}
                      onCreate={(webhook) => setWebhooks((prev) => ({
                        ...prev,
                        [projectId]: [...(prev[projectId] || []), webhook],
                      }))}
                      onToggle={(webhookId) => setWebhooks((prev) => ({
                        ...prev,
                        [projectId]: (prev[projectId] || []).map((webhook) =>
                          webhook.id === webhookId
                            ? { ...webhook, enabled: !webhook.enabled }
                            : webhook,
                        ),
                      }))}
                      onDelete={(webhookId) => setWebhooks((prev) => ({
                        ...prev,
                        [projectId]: (prev[projectId] || []).filter((webhook) => webhook.id !== webhookId),
                      }))}
                    />
                : settings()}
        </div>
        <footer className="sw-main-footer">
          <span>DEMO DATA · UTC</span>
          <span>Events from physical systems. Properties defined by you.</span>
        </footer>
      </main>
      {details()}
      {toast && (
        <div role="status" className="sw-toast">
          <FiCheck />
          <span>{toast}</span>
          <button
            className="sw-icon-button"
            aria-label="Dismiss notification"
            onClick={() => setToast("")}
          >
            <FiX />
          </button>
        </div>
      )}
    </div>
  );
}
